  route(cmd: Command, handlers: Handler[]): Handler[];
}
export class StrategyRegistry {
  private map = new Map<string, RoutingStrategy>();
  register(name: string, strategy: RoutingStrategy) { this.map.set(name, strategy); }
  get(name: string): RoutingStrategy { return this.map.get(name)!; }
